   const latest=this.dungeons().read(run.id);if(!latest?.hunt||latest.status!=='active'||latest.rewarded)return;
   const h=run.hunt!,def=huntDefinition(h.id)!;run.traps=[];run.status='complete';run.rewarded=true;run.finished=Date.now();this.dungeons().save(run);
